coding.solution:
from urllib.parse import parse_qsl

def dynamic_params(rec1, rec2):
    names = set()
    for a, b in zip(rec1, rec2):
        da, db = dict(parse_qsl(a, keep_blank_values=True)), dict(parse_qsl(b, keep_blank_values=True))
        for k in da.keys() | db.keys():
            if da.get(k) != db.get(k):
                names.add(k)
    return sorted(names)
